ben: TS draft:```ts
// resume.ts
import Redwood from '@redwood/inference';
const c = new Redwood();
async function* resumeStream(prompt: string, resumeToken?: string){
  let token = resumeToken;
  while(true){
    const stream = await c.stream({prompt, resume_token: token});
    for await(const chunk of stream){
      yield chunk.text;
      token = chunk.resume_token ?? token;
    }
    if(!token) break;
  }
}
```

