li: Python sketch:```py
# helpers.py
import base64, json, time, uuid

def encode_resume(obj):
  return base64.b64encode(json.dumps(obj).encode()).decode()

def decode_resume(token):
  return json.loads(base64.b64decode(token).decode())

def idempotent_retry(max_tries=3):
  def deco(f):
    def wrap(*a, **kw):
      rid = str(uuid.uuid4())
      for i in range(max_tries):
        try:
          headers = kw.pop('headers', {})
          headers.update({'X-Request-Id': rid})
          return f(*a, headers=headers, **kw)
        except Exception:
          if i == max_tries-1: raise
          time.sleep(0.5*(2**i))
    return wrap
  return deco
```

